-- Adds password reset and profile pictures to an existing KaziMates database. Safe to run more than once.
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,ip VARCHAR(45) NOT NULL DEFAULT '',expires_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,used_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uq_reset_token(token_hash),INDEX idx_reset_user(user_id,created_at),INDEX idx_reset_ip(ip,created_at));
CREATE TABLE IF NOT EXISTS profile_pictures(user_id BIGINT UNSIGNED PRIMARY KEY,mime_type VARCHAR(100) NOT NULL,file_size INT UNSIGNED NOT NULL,image_data LONGBLOB NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
